-- The original unique index uses Prisma's truncated name (..._payment_key).
-- Drop both names so this migration also works if the index was created with
-- the longer name on another installation.
DROP INDEX IF EXISTS "payment_request_drafts_organization_id_requester_id_payment_key";
DROP INDEX IF EXISTS "payment_request_drafts_organization_id_requester_id_payment_type_key";

-- Match the 63-character index name generated by Prisma for this schema.
CREATE INDEX "payment_request_drafts_organization_id_requester_id_payment_idx"
ON "payment_request_drafts" ("organization_id", "requester_id", "payment_type", "updated_at");
